import { MakeLogicType, afterMount, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig, ApiError } from 'lib/api'

import { dataCatalogMetricsUsageRetrieve } from './generated/api'
import type { MetricUsageApi } from './generated/api.schemas'

export interface MetricUsageLogicProps {
    name: string
}

/** The metric's slice of the latest scan, `'none'` when no scan has finished, and null until the load answers. */
export type MetricUsageState = MetricUsageApi | 'none' | null

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricUsageLogicValues {
    usage: MetricUsageState
    usageLoadFailed: boolean
    usageLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricUsageLogicActions {
    loadUsage: () => any
    loadUsageFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadUsageSuccess: (
        usage: MetricUsageState,
        payload?: any
    ) => {
        usage: MetricUsageState
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricUsageLogicMeta {
    key: string
}

export type metricUsageLogicType = MakeLogicType<
    metricUsageLogicValues,
    metricUsageLogicActions,
    MetricUsageLogicProps,
    metricUsageLogicMeta
>

export const metricUsageLogic = kea<metricUsageLogicType>([
    props({ name: '' } as MetricUsageLogicProps),
    key((props) => props.name),
    path((key) => ['products', 'data_catalog', 'frontend', 'metricUsageLogic', key]),
    loaders(({ props }) => ({
        usage: [
            null as MetricUsageState,
            {
                loadUsage: async (): Promise<MetricUsageState> => {
                    try {
                        return await dataCatalogMetricsUsageRetrieve(String(ApiConfig.getCurrentTeamId()), props.name)
                    } catch (error) {
                        if (error instanceof ApiError && error.status === 404) {
                            return 'none'
                        }
                        throw error
                    }
                },
            },
        ],
    })),
    reducers({
        usageLoadFailed: [
            false,
            {
                loadUsage: () => false,
                loadUsageFailure: () => true,
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadUsage()
    }),
])
